                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.jan_planning_overall as with targets as ( select date, replace(sales_total,\',\',\'\')::int as target_sales, 1139 as target_asp, 0.15 as discount_pct, ((replace(sales_total,\',\',\'\')::int*0.13)/(0.87))::int as target_discount_amount, (replace(sales_total,\',\',\'\')::int/1139)::int as target_quantity, 1265061 as target_spend_online, 1968228 as target_total_spend, 1007893 as target_fb_spend_online, 1427893 as target_fb_spend_total, 202501 as target_google_spend_online, 272501 as target_google_spend_total, 38000 as target_retention_online, 10667 as target_retention_offline, 16667 as target_affiliate from SNITCH_DB.MAPLEMONK.OCT_SHOPIFY_26 where date is not null ), sales_discount as ( select date, discount_pct, discount, sales from ( select order_timestamp::date as date, case when lower(ifnull(discount_code,\'others\')) like \'%eco%\' or lower(ifnull(discount_code,\'others\')) like \'%influ%\' or lower(ifnull(discount_code,\'others\')) like \'%rms%\' or tags = \'FLITS_LOGICERP\' or lower(ifnull(discount_code,\'others\')) like \'%creator%\' then 1 else 0 end as filters, sum(discount)/sum(discount+gross_sales) as discount_pct, sum(discount)::int as discount, sum(gross_sales)::int as sales from snitch_db.maplemonk.fact_items_snitch where order_status = \'Shopify_Processed\' and date_trunc(\'month\',order_timestamp::date) = date_trunc(\'month\',current_date) group by 1,2 ) where filters = 0 ), main_spends as ( select date, sum(case when channel = \'Facebook\' then spend end)::int -sum(case when channel = \'Facebook\' and lower(ad_name) like \'offline%\' then ifnull(spend,0) end)::int -sum(case when channel = \'Facebook\' and lower(adset_name) like \'offline%\' then ifnull(spend,0) end)::int -sum(case when channel = \'Facebook\' and lower(campaign_name) like \'offline%\' then ifnull(spend,0) end)::int as online_facebook, sum(case when channel = \'Facebook\' then spend end)::int as total_facebook, sum(case when channel = \'Facebook\' and lower(ad_name) like \'offline%\' then ifnull(spend,0) end)::int +sum(case when channel = \'Facebook\' and lower(adset_name) like \'offline%\' then ifnull(spend,0) end)::int +sum(case when channel = \'Facebook\' and lower(campaign_name) like \'offline%\' then ifnull(spend,0) end)::int as offline_facebook, sum(case when channel = \'Google\' then spend end)::int -ifnull(sum(case when channel = \'Google\' and lower(ad_name) like \'offline%\' then ifnull(spend,0) end)::int,0) -ifnull(sum(case when channel = \'Google\' and lower(adset_name) like \'offline%\' then ifnull(spend,0) end)::int,0) -ifnull(sum(case when channel = \'Google\' and lower(campaign_name) like \'offline%\' then ifnull(spend,0) end)::int,0) as online_Google, sum(case when channel = \'Google\' then spend end)::int as total_Google, ifnull(sum(case when channel = \'Google\' and lower(ad_name) like \'offline%\' then ifnull(spend,0) end)::int,0) +ifnull(sum(case when channel = \'Google\' and lower(adset_name) like \'offline%\' then ifnull(spend,0) end)::int,0) +ifnull(sum(case when channel = \'Google\' and lower(campaign_name) like \'offline%\' then ifnull(spend,0) end)::int,0) as offline_Google, sum(case when channel = \'Affiliates\' then spend end)::int as affilates from snitch_db.maplemonk.marketing_consolidated_snitch where date_trunc(\'month\',date) = date_trunc(\'month\',current_date) group by 1 ), retention_online as ( SELECT run_date as date, SUM(SPENDS)::int AS retention_online FROM snitch_db.maplemonk.campaign_reports_summary WHERE CHANNEL IN (\'Sms\', \'WhatsApp\') and date_trunc(\'month\',run_date) = date_trunc(\'month\',current_date) group by 1 ), retention_offline as ( SELECT run_date as date, SUM(SPENDS)::int AS retention_offline FROM snitch_db.maplemonk.campaign_reports_summary_offline WHERE CHANNEL IN (\'Sms\', \'WhatsApp\') and date_trunc(\'month\',run_date) = date_trunc(\'month\',current_date) group by 1 ), north_south_pre as ( select order_date, CASE WHEN warehouse_name like \'%NORTH%\' then \'NORTH\' when warehouse_name like \'%SAPL%\' then \'SOUTH\' else \'OMNI/QCOM\' end as location, count(saleorderitemcode) as units, sum(suborder_quantity) as quant from snitch_db.maplemonk.unicommerce_fact_items_intermediate_2024 where marketplace_mapped = \'SHOPIFY\' and warehouse_name like \'%SAPL%\' group by 1,2 ), north_south as ( select order_date as date, sum(case when location = \'NORTH\' then units end) as north, sum(case when location = \'SOUTH\' then units end) as south, sum(case when location = \'OMNI/QCOM\' then units end) as omni from north_south_pre group by 1 ), actuals as ( select a.date, a.sales as actual_sales, a.discount_pct as actual_discount_pct, a.discount as actual_discount, online_facebook as actual_online_facebook, offline_facebook as actual_offline_facebook, total_facebook as actual_total_facebook, online_google as actual_online_google, offline_google as actual_offline_google, total_google as actual_total_google, affilates as actual_affilates, c.retention_online as actual_retention_online, e.retention_offline as actual_retention_offline, (online_facebook+online_google+ifnull(affilates,0)+ifnull(c.retention_online,0)) as actual_total_online_spends, (offline_facebook+offline_google+ifnull(e.retention_offline,0)) as actual_total_offline_spends, (total_facebook+total_google+ifnull(c.retention_online,0)+ifnull(e.retention_offline,0)+ifnull(affilates,0)) as actual_total_spends, north as actual_north_quantity, south as actual_south_quantity from sales_discount a left join main_spends b on a.date = b.date left join retention_online c on a.date = c.date left join retention_offline e on a.date = e.date left join north_south d on a.date = d.date order by a.date asc ) select a.*, b.actual_sales, b.actual_discount_pct, b.actual_discount, actual_online_facebook, actual_offline_facebook, actual_total_facebook, actual_online_google, actual_offline_google, actual_total_google, actual_affilates, actual_retention_online, actual_retention_offline, actual_total_online_spends, actual_total_offline_spends, actual_total_spends, b.actual_north_quantity, b.actual_south_quantity, current_date as today_date from targets a left join actuals b on a.date = b.date ; create or replace table snitch_db.maplemonk.cat_l1_july26_sales_target_int as select category, l1_category as l1_category, replace(target_sales_01, \',\', \'\')::int as target_sales_01, replace(target_sales_02, \',\', \'\')::int as target_sales_02, replace(target_sales_03, \',\', \'\')::int as target_sales_03, replace(target_sales_04, \',\', \'\')::int as target_sales_04, replace(target_sales_05, \',\', \'\')::int as target_sales_05, replace(target_sales_06, \',\', \'\')::int as target_sales_06, replace(target_sales_07, \',\', \'\')::int as target_sales_07, replace(target_sales_08, \',\', \'\')::int as target_sales_08, replace(target_sales_09, \',\', \'\')::int as target_sales_09, replace(target_sales_10, \',\', \'\')::int as target_sales_10, replace(target_sales_11, \',\', \'\')::int as target_sales_11, replace(target_sales_12, \',\', \'\')::int as target_sales_12, replace(target_sales_13, \',\', \'\')::int as target_sales_13, replace(target_sales_14, \',\', \'\')::int as target_sales_14, replace(target_sales_15, \',\', \'\')::int as target_sales_15, replace(target_sales_16, \',\', \'\')::int as target_sales_16, replace(target_sales_17, \',\', \'\')::int as target_sales_17, replace(target_sales_18, \',\', \'\')::int as target_sales_18, replace(target_sales_19, \',\', \'\')::int as target_sales_19, replace(target_sales_20, \',\', \'\')::int as target_sales_20, replace(target_sales_21, \',\', \'\')::int as target_sales_21, replace(target_sales_22, \',\', \'\')::int as target_sales_22, replace(target_sales_23, \',\', \'\')::int as target_sales_23, replace(target_sales_24, \',\', \'\')::int as target_sales_24, replace(target_sales_25, \',\', \'\')::int as target_sales_25, replace(target_